import gmpy2
from gmpy2 import mpz, isqrt, is_square

N = mpz('')

# Implement Fermat's factorization method
def fermat_factor(N, max_iter=10**7):
    a = isqrt(N)
    if a * a < N:
        a += 1
    b2 = a*a - N
    count = 0
    while count < max_iter:
        if is_square(b2):
            b = isqrt(b2)
            p = a + b
            q = a - b
            if p * q == N:
                return int(p), int(q)
        a += 1
        b2 = a*a - N
        count += 1
    return None

result = fermat_factor(N)
if result:
    print(f"Found factors:\np = {result[0]}\nq = {result[1]}")
else:
    print("No factors found (try increasing max_iter).")

import gmpy2
from gmpy2 import mpz, is_square, is_prime, gcd, iroot

N = mpz()

results = []

# Check perfect k-th power for k = 2 through 5
for k in range(2,6):
    root, exact = iroot(N, k)
    if exact:
        results.append(f"N IS a perfect {k}-th power, root = {root}")
    else:
        results.append(f"N is NOT a perfect {k}-th power.")

# Try to factor N with small primes
prime_factors = []
test_limit = 1000000
M = N
for p in range(2, test_limit):
    if gmpy2.is_prime(p) and M % p == 0:
        count = 0
        while M % p == 0:
            M //= p
            count += 1
        prime_factors.append((p, count))
        if M == 1:
            break
if len(prime_factors) > 0:
    results.append(f"Small prime factors found: {prime_factors}")
    if M != 1:
        results.append(f"Remaining cofactor: {M}")
else:
    results.append("No small prime factors up to 1 million.")

# Try Pollard's p-1 for small bounds
from gmpy2 import powmod

def pollard_p1(n, B=100000):
    a = mpz(2)
    for j in range(2, B):
        a = powmod(a, j, n)
    d = gcd(a-1, n)
    if d > 1 and d < n:
        return d
    return None

pp1_factor = pollard_p1(N, 100000)
if pp1_factor:
    results.append(f"Pollard's p-1 found nontrivial factor: {pp1_factor}")
    results.append(f"Quotient: {N // pp1_factor}")
else:
    results.append("Pollard's p-1 did not find a nontrivial factor using bound 100000.")

# Print results
for line in results:
    print(line)

